import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { adminApi } from '../api/admin';
import { useAuth } from '../context/AuthContext';
import { useShop } from '../context/ShopContext';
import { CatalogStatus, ItemType } from '../types';
import ConfirmModal from '../components/ConfirmModal';
import {
  Package,
  Plus,
  Edit,
  Archive,
  RefreshCw,
  Loader2,
  AlertCircle,
  Eye,
  CheckCircle2,
  GitBranch,
  ChevronLeft,
  ChevronRight,
  Search,
} from 'lucide-react';

const OWNER_STATUSES: CatalogStatus[] = ['draft', 'review'];
const STAFF_STATUSES: CatalogStatus[] = [
  'draft',
  'review',
  'published',
  'out_of_stock',
  'backorder',
  'archived',
  'discontinued',
];

export const CreatorCatalog: React.FC = () => {
  const { hasRole } = useAuth();
  const { formatPrice, deleteItem } = useShop();

  const isStaff = hasRole(['admin', 'super_admin', 'moderator']);

  const [catalogGroups, setCatalogGroups] = useState<Array<{ type: string; items: any[]; total: number }>>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [creatorFilterInput, setCreatorFilterInput] = useState('');
  const [appliedCreatorId, setAppliedCreatorId] = useState('');

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [selectedType, setSelectedType] = useState<string>('all');
  const [archivingTarget, setArchivingTarget] = useState<{ type: string; id: string; title: string } | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Lifecycle Status Modal State
  const [statusModalItem, setStatusModalItem] = useState<{
    itemType: ItemType;
    id: string;
    title: string;
    currentStatus: string;
  } | null>(null);
  const [targetStatus, setTargetStatus] = useState<CatalogStatus>('review');
  const [statusReason, setStatusReason] = useState('');
  const [statusSubmitting, setStatusSubmitting] = useState(false);

  const fetchCreatorItems = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await adminApi.getCreatorCatalog(
        page,
        20,
        isStaff && appliedCreatorId.trim() ? appliedCreatorId.trim() : undefined
      );
      setCatalogGroups(res.catalog);
      setTotalPages(Math.max(1, res.pagination?.totalPages || 1));
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load creator catalog.');
    } finally {
      setLoading(false);
    }
  }, [page, isStaff, appliedCreatorId]);

  useEffect(() => {
    fetchCreatorItems();
  }, [fetchCreatorItems]);

  const handleConfirmArchive = async () => {
    if (!archivingTarget) return;
    const { type, id, title } = archivingTarget;
    setArchivingTarget(null);
    setDeletingId(id);
    setError(null);
    setNotice(null);
    try {
      await deleteItem(type as any, id);
      setNotice(`Archived "${title}" successfully.`);
      await fetchCreatorItems();
    } catch (err: any) {
      setError(err?.error || err?.message || 'Failed to archive release.');
    } finally {
      setDeletingId(null);
    }
  };

  const openStatusModal = (itemType: ItemType, id: string, title: string, currentStatus: string) => {
    const allowed = isStaff ? STAFF_STATUSES : OWNER_STATUSES;
    setStatusModalItem({ itemType, id, title, currentStatus });
    setTargetStatus(
      allowed.includes(currentStatus as CatalogStatus)
        ? (currentStatus as CatalogStatus)
        : allowed[0]
    );
    setStatusReason('');
  };

  const handleStatusSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusModalItem) return;
    setStatusSubmitting(true);
    setError(null);
    setNotice(null);
    try {
      await adminApi.updateCatalogStatus(
        statusModalItem.itemType,
        statusModalItem.id,
        targetStatus,
        statusReason
      );
      setNotice(`Updated "${statusModalItem.title}" status to "${targetStatus}".`);
      setStatusModalItem(null);
      await fetchCreatorItems();
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not update catalog lifecycle status.');
    } finally {
      setStatusSubmitting(false);
    }
  };

  const allItems = catalogGroups.flatMap(group =>
    (group.items || []).map(item => ({ ...item, catalogType: group.type || item.type }))
  );

  const filteredItems =
    selectedType === 'all'
      ? allItems
      : allItems.filter(i => (i.catalogType || i.type) === selectedType);

  const getStatusBadge = (status: string, isActive?: boolean) => {
    const s = (status || (isActive ? 'published' : 'draft')).toLowerCase();
    switch (s) {
      case 'published':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
            published
          </span>
        );
      case 'review':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20">
            review
          </span>
        );
      case 'out_of_stock':
      case 'backorder':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20">
            {s}
          </span>
        );
      case 'archived':
      case 'discontinued':
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-200 dark:bg-slate-800 text-slate-500 border border-slate-300 dark:border-slate-700">
            {s}
          </span>
        );
      default:
        return (
          <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
            draft
          </span>
        );
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-wider text-emerald-600 dark:text-emerald-400 font-bold">
              STUDIO WORKSPACE
            </span>
            <span className="text-[11px] font-mono text-slate-500 dark:text-slate-400">
              Owned Releases · All Lifecycle States
            </span>
          </div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white mt-1">
            Creator Catalog Management
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            Manage drafts, lifecycle transitions, uploads, and archived catalog releases.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <Link
            to="/admin/product/new"
            className="px-3.5 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors"
          >
            <Plus size={13} />
            <span>New Product</span>
          </Link>
          <Link
            to="/admin/course/new"
            className="px-3.5 py-2 rounded-xl bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors"
          >
            <Plus size={13} />
            <span>New Course</span>
          </Link>
          <Link
            to="/admin/bundle/new"
            className="px-3.5 py-2 rounded-xl bg-purple-600 hover:bg-purple-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors"
          >
            <Plus size={13} />
            <span>New Bundle</span>
          </Link>
          {isStaff && (
            <Link
              to="/admin/subscription/new"
              className="px-3.5 py-2 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors"
            >
              <Plus size={13} />
              <span>New Plan</span>
            </Link>
          )}
          <button
            type="button"
            onClick={fetchCreatorItems}
            disabled={loading}
            className="p-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-slate-500 transition-colors"
            aria-label="Refresh creator catalog"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
          </button>
        </div>
      </div>

      {notice && (
        <div className="mb-6 p-3.5 rounded-xl bg-emerald-500/10 border border-emerald-500/25 text-xs text-emerald-700 dark:text-emerald-300 flex items-center gap-2">
          <CheckCircle2 size={15} className="shrink-0" />
          <span>{notice}</span>
        </div>
      )}

      {error && (
        <div className="mb-6 p-3.5 rounded-xl bg-rose-500/10 border border-rose-500/25 text-xs text-rose-700 dark:text-rose-300 flex items-center gap-2">
          <AlertCircle size={15} className="shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {/* Filter Tabs + Staff creatorId filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div className="flex items-center gap-2 overflow-x-auto pb-1">
          {['all', 'product', 'course', 'bundle', 'subscription'].map(tab => (
            <button
              key={tab}
              type="button"
              onClick={() => setSelectedType(tab)}
              className={`px-3.5 py-1.5 rounded-lg text-xs font-semibold capitalize transition-colors ${
                selectedType === tab
                  ? 'bg-slate-900 dark:bg-white text-white dark:text-slate-950'
                  : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-900'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {isStaff && (
          <form
            onSubmit={e => {
              e.preventDefault();
              setPage(1);
              setAppliedCreatorId(creatorFilterInput);
            }}
            className="flex items-center gap-2"
          >
            <div className="relative">
              <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input
                type="text"
                value={creatorFilterInput}
                onChange={e => setCreatorFilterInput(e.target.value)}
                placeholder="Filter by Creator ID..."
                className="pl-8 pr-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 bg-white dark:bg-[#101216] text-xs font-mono text-slate-800 dark:text-slate-200"
              />
            </div>
            <button
              type="submit"
              className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 text-xs font-semibold text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800"
            >
              Filter
            </button>
            {appliedCreatorId && (
              <button
                type="button"
                onClick={() => {
                  setCreatorFilterInput('');
                  setAppliedCreatorId('');
                  setPage(1);
                }}
                className="text-xs text-slate-500 hover:text-slate-800 dark:hover:text-white"
              >
                Clear
              </button>
            )}
          </form>
        )}
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
          <Loader2 size={32} className="animate-spin text-emerald-500 mb-3" />
          <span className="text-xs font-mono">Loading creator workspace...</span>
        </div>
      ) : filteredItems.length === 0 ? (
        <div className="p-12 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 text-center max-w-md mx-auto">
          <Package size={30} className="text-slate-400 mx-auto mb-3" />
          <h2 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-1">
            No Releases Found
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-6">
            You do not have any published or draft items matching these criteria.
          </p>
          <Link
            to="/admin/product/new"
            className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-xl text-xs font-semibold"
          >
            <Plus size={13} />
            <span>Create Release</span>
          </Link>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredItems.map(item => {
              const id = item._id || item.id;
              const rawType = String(item.catalogType || item.type || 'product').toLowerCase();
              const normalizedType: ItemType =
                rawType === 'course'
                  ? 'course'
                  : rawType === 'bundle'
                  ? 'bundle'
                  : rawType === 'subscription'
                  ? 'subscription'
                  : 'product';

              const editUrl =
                normalizedType === 'course'
                  ? `/admin/course/edit/${id}`
                  : normalizedType === 'bundle'
                  ? `/admin/bundle/edit/${id}`
                  : normalizedType === 'subscription'
                  ? `/admin/subscription/edit/${id}`
                  : `/admin/product/edit/${id}`;

              const canEditThisItem = normalizedType !== 'subscription' || isStaff;
              const title = item.name || item.title || 'Untitled';

              return (
                <div
                  key={`${normalizedType}-${id}`}
                  className="p-5 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between"
                >
                  <div>
                    <div className="flex items-center justify-between gap-2 mb-3">
                      <span className="text-[10px] font-mono uppercase px-2 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300">
                        {normalizedType}
                      </span>
                      {getStatusBadge(item.status, item.isActive)}
                    </div>

                    <h3 className="font-display text-base font-bold text-slate-900 dark:text-white line-clamp-1 mb-1">
                      {title}
                    </h3>

                    <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 mb-3">
                      {item.description || 'No description provided.'}
                    </p>

                    <div className="text-xs font-mono tabular-nums font-bold text-slate-900 dark:text-white mb-2">
                      {formatPrice(item.price, item.currency)}
                    </div>
                  </div>

                  <div className="pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between gap-2">
                    <div className="flex items-center gap-1.5">
                      {canEditThisItem && (
                        <Link
                          to={editUrl}
                          className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
                        >
                          <Edit size={12} />
                          <span>Edit</span>
                        </Link>
                      )}
                      {canEditThisItem && (
                        <button
                          type="button"
                          onClick={() => openStatusModal(normalizedType, id, title, item.status || 'draft')}
                          className="px-2.5 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-800 text-xs font-semibold text-slate-600 dark:text-slate-300 inline-flex items-center gap-1 transition-colors"
                          title="Change lifecycle status"
                        >
                          <GitBranch size={12} />
                          <span>Status</span>
                        </button>
                      )}
                      <Link
                        to={`/item/${item.slug || id}`}
                        className="p-1.5 rounded-lg text-slate-400 hover:text-slate-900 dark:hover:text-white transition-colors"
                        title="View public storefront page"
                      >
                        <Eye size={14} />
                      </Link>
                    </div>

                    {canEditThisItem && (
                      <button
                        type="button"
                        disabled={deletingId === id}
                        onClick={() => setArchivingTarget({ type: normalizedType, id, title })}
                        className="p-1.5 rounded-lg text-slate-400 hover:text-amber-600 disabled:opacity-50 transition-colors"
                        title="Archive release"
                      >
                        <Archive size={14} />
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          {totalPages > 1 && (
            <div className="mt-8 flex items-center justify-center gap-3 text-xs">
              <button
                type="button"
                disabled={page <= 1}
                onClick={() => setPage(p => Math.max(1, p - 1))}
                className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 disabled:opacity-40 inline-flex items-center gap-1"
              >
                <ChevronLeft size={14} /> Previous
              </button>
              <span className="font-mono text-slate-500">
                Page {page} of {totalPages}
              </span>
              <button
                type="button"
                disabled={page >= totalPages}
                onClick={() => setPage(p => Math.min(totalPages, p + 1))}
                className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 disabled:opacity-40 inline-flex items-center gap-1"
              >
                Next <ChevronRight size={14} />
              </button>
            </div>
          )}
        </>
      )}

      {/* Archive Confirmation Modal */}
      <ConfirmModal
        isOpen={Boolean(archivingTarget)}
        onClose={() => setArchivingTarget(null)}
        onConfirm={handleConfirmArchive}
        title="Archive Catalog Release"
        message={`Archive "${archivingTarget?.title || ''}"? Historical orders and existing customer entitlements are preserved, while storefront visibility is removed.`}
        confirmText="Archive Release"
        variant="warning"
      />

      {/* Lifecycle Status Transition Modal */}
      {statusModalItem && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-xs p-4">
          <div className="w-full max-w-md rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 p-6 shadow-xl space-y-4">
            <h2 className="text-base font-bold text-slate-900 dark:text-white">
              Update Lifecycle Status
            </h2>
            <p className="text-xs text-slate-500 dark:text-slate-400">
              {statusModalItem.title} ({statusModalItem.itemType})
            </p>
            <form onSubmit={handleStatusSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">
                  Target Status
                </label>
                <select
                  value={targetStatus}
                  onChange={e => setTargetStatus(e.target.value as CatalogStatus)}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900 text-xs font-mono text-slate-900 dark:text-white"
                >
                  {(isStaff ? STAFF_STATUSES : OWNER_STATUSES).map(s => (
                    <option key={s} value={s}>
                      {s}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">
                  Reason (optional, max 500 chars)
                </label>
                <textarea
                  rows={2}
                  maxLength={500}
                  value={statusReason}
                  onChange={e => setStatusReason(e.target.value)}
                  placeholder="e.g. Ready for storefront review"
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900 text-xs text-slate-900 dark:text-white"
                />
              </div>
              <div className="flex justify-end gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => setStatusModalItem(null)}
                  className="px-4 py-2 rounded-lg border border-slate-200 dark:border-slate-800 text-xs font-semibold"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={statusSubmitting}
                  className="px-4 py-2 rounded-lg bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white text-xs font-semibold"
                >
                  {statusSubmitting ? 'Updating...' : 'Apply Status'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreatorCatalog;
